            for aq_tile in remaining:
                if not can_place_district_on_tile("AQUEDUCT", aq_tile, cc_id, used):
                    continue

                test_placements = dict(base_placements)
                test_placements["AQUEDUCT"] = aq_tile

                total = 0
                bonuses = {}
                for dname in combo:
                    b = compute_adjacency(dname, test_placements[dname], test_placements)
                    bonuses[dname] = b
                    total += b

                if total > best_total_2:
                    best_total_2 = total
                    best_solution_2 = {
                        "cc": cc_id,
                        "combo": list(combo) + ["AQUEDUCT"],
                        "tiles": list(perm) + [aq_tile],
                        "bonuses": dict(bonuses),
                        "total": total,
                        "all_placements": dict(test_placements)
                    }
                    print(f"New best (aq): total={total}, cc={id_to_xy(cc_id)}, "
                          f"aq={id_to_xy(aq_tile)}, bonuses={bonuses}")

                # Also try adding dam on top of aqueduct
                used2 = used | {aq_tile}
                remaining2 = [t for t in remaining if t != aq_tile]
                for dam_tile in remaining2:
                    if not can_place_district_on_tile("DAM", dam_tile, cc_id, used2):
                        continue

                    test_placements2 = dict(test_placements)
                    test_placements2["DAM"] = dam_tile

                    total2 = 0
                    bonuses2 = {}
                    for dname in combo:
                        b = compute_adjacency(dname, test_placements2[dname], test_placements2)
                        bonuses2[dname] = b
                        total2 += b

                    if total2 > best_total_2:
                        best_total_2 = total2
                        best_solution_2 = {
                            "cc": cc_id,
                            "combo": list(combo) + ["AQUEDUCT", "DAM"],
                            "tiles": list(perm) + [aq_tile, dam_tile],
                            "bonuses": dict(bonuses2),
                            "total": total2,
                            "all_placements": dict(test_placements2)
                        }
                        print(f"New best (aq+dam): total={total2}, cc={id_to_xy(cc_id)}, "
                              f"aq={id_to_xy(aq_tile)}, dam={id_to_xy(dam_tile)}, bonuses={bonuses2}")

            # Try dam only
            for dam_tile in remaining:
                if not can_place_district_on_tile("DAM", dam_tile, cc_id, used):
                    continue

                test_placements = dict(base_placements)
                test_placements["DAM"] = dam_tile

                total = 0
                bonuses = {}
                for dname in combo:
                    b = compute_adjacency(dname, test_placements[dname], test_placements)
                    bonuses[dname] = b
                    total += b

                if total > best_total_2:
                    best_total_2 = total
                    best_solution_2 = {
                        "cc": cc_id,
                        "combo": list(combo) + ["DAM"],
                        "tiles": list(perm) + [dam_tile],
                        "bonuses": dict(bonuses),
                        "total": total,
                        "all_placements": dict(test_placements)
                    }
                    print(f"New best (dam): total={total}, cc={id_to_xy(cc_id)}, "
                          f"dam={id_to_xy(dam_tile)}, bonuses={bonuses}")


if best_total_2 > best_total:
    best_total = best_total_2
    best_solution = best_solution_2

# ============================================================
# Output
# ============================================================
print(f"\n=== FINAL SOLUTION ===")
print(f"Total adjacency: {best_total}")
if best_solution:
    cc = best_solution['cc']
    print(f"City center: {id_to_xy(cc)}")
    for i, dname in enumerate(best_solution['combo']):
        dtile = best_solution['tiles'][i]
        b = best_solution['bonuses'].get(dname, 0)
        print(f"  {dname}: {id_to_xy(dtile)}, bonus={b}")

    # Write output JSON
    cc_xy = list(id_to_xy(cc))
    out_placements = {}
    out_bonuses = {}
    for i, dname in enumerate(best_solution['combo']):
        dtile = best_solution['tiles'][i]
        out_placements[dname] = list(id_to_xy(dtile))
        if dname in ("AQUEDUCT", "DAM"):
            out_bonuses[dname] = 0
        else:
            out_bonuses[dname] = best_solution['bonuses'][dname]

    output = {
        "city_center": cc_xy,
        "placements": out_placements,
        "adjacency_bonuses": {k: v for k, v in out_bonuses.items() if k not in ("AQUEDUCT", "DAM")},
        "total_adjacency": best_total
    }

